{"path":"server.js","content":"import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { createStore, ValidationError } from './store.js';

const root = dirname(fileURLToPath(import.meta.url));
const assets = new Map([
  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
  ['/favicon.svg', ['favicon.svg', 'image/svg+xml']]
]);

function json(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(value));
}

async function body(req) {
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 32_000) {
      const error = new ValidationError('Request is too large.');
      error.status = 413;
      throw error;
    }
  }
  try {
    const value = JSON.parse(text);
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error();
    return value;
  } catch {
    throw new ValidationError('Send a JSON object.');
  }
}

export function createApp({ dataFile = join(root, 'data', 'books.json'), publicDir = join(root, 'public') } = {}) {
  const store = createStore(dataFile);
  return http.createServer(async (req, res) => {
    try {
      const path = new URL(req.url, 'http://localhost').pathname;
      if (path === '/api/books') {
        if (req.method === 'GET') return json(res, 200, await store.list());
        if (req.method === 'POST') return json(res, 201, await store.add(await body(req)));
      }
      const match = path.match(/^\/api\/books\/([^/]+)$/);
      if (match) {
        const id = match[1];
        if (req.method === 'GET') {
          const book = await store.get(id);
          return book ? json(res, 200, book) : json(res, 404, { error: 'Book not found.' });
        }
        if (req.method === 'PATCH') {
          const book = await store.update(id, await body(req));
          return book ? json(res, 200, book) : json(res, 404, { error: 'Book not found.' });
        }
        if (req.method === 'DELETE') {
          const removed = await store.remove(id);
          return removed ? json(res, 200, { deleted: true }) : json(res, 404, { error: 'Book not found.' });
        }
      }
      if (req.method === 'GET') {
        const asset = assets.get(path);
        const isPage = path === '/' || /^\/books\/[^/]+\/?$/.test(path);
        if (asset || isPage) {
          const [name, type] = asset ?? ['index.html', 'text/html; charset=utf-8'];
          const content = await readFile(join(publicDir, name));
          res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-cache' });
          return res.end(content);
        }
      }
      return json(res, 404, { error: 'Not found.' });
    } catch (error) {
      if (error instanceof ValidationError) return json(res, error.status ?? 400, { error: error.message });
      console.error(error);
      return json(res, 500, { error: 'Something went wrong. Please try again.' });
    }
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const port = Number(process.env.PORT) || 3000;
  createApp().listen(port, () => console.log(`Between Pages is running at http://localhost:${port}`));
}
"}

