{"path":"public/app.js","content":"const dashboard = document.querySelector('#dashboard');
const detail = document.querySelector('#detail');
const dialog = document.querySelector('#book-dialog');
const form = document.querySelector('#book-form');
const toast = document.querySelector('#toast');

const palettes = [
  ['#31534a', '#f2e7c8', '#d1ba87'],
  ['#ad694e', '#fff0d9', '#f4c99e'],
  ['#727e9a', '#faf1d7', '#d7d0af'],
  ['#b08d62', '#fff5dc', '#e7d2a4'],
  ['#4c555e', '#f5e7d3', '#baab93'],
  ['#8e665f', '#f9eadc', '#e6bea8']
];

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
}

function cover(book) {
  const index = [...book.title].reduce((sum, letter) => sum + letter.charCodeAt(0), 0) % palettes.length;
  const [background, foreground, detailColor] = palettes[index];
  return `<div class="book-cover" style="--cover-bg:${background};--cover-fg:${foreground};--cover-detail:${detailColor}" aria-label="Cover for ${escapeHtml(book.title)}"><span class="cover-top">${escapeHtml(book.author)}</span><span class="cover-center">${escapeHtml(book.title)}</span><span class="cover-bottom">✳ &nbsp; BETWEEN PAGES &nbsp; ✳</span></div>`;
}

async function request(path, options = {}) {
  let response;
  try {
    response = await fetch(path, {
      ...options,
      headers: { 'Content-Type': 'application/json', ...options.headers }
    });
  } catch {
    throw new Error('Could not connect. Please try again.');
  }
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong.');
  return data;
}

let toastTimer;
function notify(message) {
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 3200);
}

function bookCard(book) {
  const url = `/books/${encodeURIComponent(book.id)}`;
  const finished = book.status === 'finished';
  return `<article class="book-card">
    <div class="book-card-body"><a class="cover-link" href="${url}" aria-label="View ${escapeHtml(book.title)}">${cover(book)}</a>
      <div class="book-card-info"><span class="card-status ${finished ? 'finished' : ''}">${finished ? 'Finished' : 'Reading now'}</span>
        <h3><a href="${url}">${escapeHtml(book.title)}</a></h3><p class="card-author">by ${escapeHtml(book.author)}</p>
        ${book.notes ? `<p class="card-notes">“${escapeHtml(book.notes)}”</p>` : ''}
      </div></div>
    <div class="book-card-footer"><a class="card-detail-link" href="${url}">View book <span aria-hidden="true">↗</span></a>
      <button class="card-action" type="button" data-book-id="${escapeHtml(book.id)}" data-status="${finished ? 'reading' : 'finished'}">${finished ? 'Move to reading' : 'Mark as finished'}</button>
    </div></article>`;
}

function emptyShelf(finished) {
  return `<div class="empty-shelf"><div class="empty-illustration" aria-hidden="true">${finished ? '✦' : '◈'}</div><div><h3>${finished ? 'No finished books yet.' : 'A fresh page awaits.'}</h3><p>${finished ? 'When you finish a book, it will find a home here.' : 'Add the book you’re reading to start your shelf.'}</p>${finished ? '' : '<button type="button" data-open-form>Add your first book →</button>'}</div></div>`;
}

async function loadShelf() {
  try {
    const books = await request('/api/books');
    const reading = books.filter((book) => book.status === 'reading').sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    const finished = books.filter((book) => book.status === 'finished').sort((a, b) => (b.finishedAt || b.createdAt).localeCompare(a.finishedAt || a.createdAt));
    document.querySelector('#reading-count').textContent = reading.length;
    document.querySelector('#finished-count').textContent = finished.length;
    document.querySelector('#reading-badge').textContent = reading.length;
    document.querySelector('#finished-badge').textContent = finished.length;
    document.querySelector('#reading-list').innerHTML = reading.length ? reading.map(bookCard).join('') : emptyShelf(false);
    document.querySelector('#finished-list').innerHTML = finished.length ? finished.map(bookCard).join('') : emptyShelf(true);
  } catch (error) {
    document.querySelector('#reading-list').innerHTML = `<div class="empty-shelf"><div><h3>Couldn’t load your shelf.</h3><p>${escapeHtml(error.message)}</p><button type="button" data-retry>Try again →</button></div></div>`;
    document.querySelector('#finished-list').innerHTML = '';
  }
}

function notFound() {
  detail.innerHTML = `<div class="not-found"><div class="section-kicker">PAGE NOT FOUND</div><h1>That book isn't on this shelf.</h1><p>It may have been removed, or the link might be incomplete.</p><a href="/" class="button button-dark">Back to my shelf</a></div>`;
  document.title = 'Book not found — Between Pages';
}

function renderDetail(book) {
  const finished = book.status === 'finished';
  document.title = `${book.title} — Between Pages`;
  detail.innerHTML = `<a class="breadcrumb" href="/"><span class="breadcrumb-arrow" aria-hidden="true">←</span> Back to my shelf</a>
    <div class="detail-layout"><div class="detail-art">${cover(book)}</div><div class="detail-content">
      <span class="detail-status ${finished ? 'finished' : ''}">${finished ? 'FINISHED' : 'CURRENTLY READING'}</span>
      <h1>${escapeHtml(book.title)}</h1><p class="detail-author">by ${escapeHtml(book.author)}</p>
      <div class="detail-rule"></div>
      <div class="detail-notes-heading"><h2>Your notes</h2><button class="text-button" type="button" data-edit-notes>${book.notes ? 'Edit notes ↗' : 'Add a note ↗'}</button></div>
      <p class="notes-text ${book.notes ? '' : 'is-empty'}">${book.notes ? escapeHtml(book.notes) : 'No notes yet. What would you like to remember about this one?'}</p>
      <div class="detail-actions"><button type="button" class="button button-dark" data-toggle-status>${finished ? '↶ &nbsp; Move back to reading' : '✓ &nbsp; Mark as finished'}</button><button type="button" class="button button-outline" data-share>↗ &nbsp; Copy book link</button></div>
      <div class="detail-bottom"><span class="detail-date">${finished && book.finishedAt ? `Finished ${new Date(book.finishedAt).toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}` : 'On your reading shelf'}</span><button type="button" class="text-button delete-button" data-delete>Remove book</button></div>
    </div></div>`;

  detail.querySelector('[data-toggle-status]').addEventListener('click', async (event) => {
    event.currentTarget.disabled = true;
    try {
      const updated = await request(`/api/books/${encodeURIComponent(book.id)}`, { method: 'PATCH', body: JSON.stringify({ status: finished ? 'reading' : 'finished' }) });
      renderDetail(updated);
      notify(finished ? 'Moved back to currently reading.' : 'Another story finished. Well done!');
    } catch (error) { event.currentTarget.disabled = false; notify(error.message); }
  });
  detail.querySelector('[data-edit-notes]').addEventListener('click', () => {
    const paragraph = detail.querySelector('.notes-text');
    const editor = document.createElement('div');
    editor.className = 'notes-editor';
    editor.innerHTML = `<label class="section-kicker" for="edit-notes">YOUR THOUGHTS</label><textarea id="edit-notes" maxlength="5000" rows="6"></textarea><div class="notes-editor-actions"><button type="button" class="button button-plain" data-cancel>Cancel</button><button type="button" class="button button-dark" data-save>Save notes</button></div>`;
    paragraph.replaceWith(editor);
    const textarea = editor.querySelector('textarea');
    textarea.value = book.notes;
    textarea.focus();
    detail.querySelector('[data-edit-notes]').hidden = true;
    editor.querySelector('[data-cancel]').addEventListener('click', () => renderDetail(book));
    editor.querySelector('[data-save]').addEventListener('click', async (event) => {
      event.currentTarget.disabled = true;
      try {
        const updated = await request(`/api/books/${encodeURIComponent(book.id)}`, { method: 'PATCH', body: JSON.stringify({ notes: textarea.value }) });
        renderDetail(updated);
        notify('Your notes have been saved.');
      } catch (error) { event.currentTarget.disabled = false; notify(error.message); }
    });
  });
  detail.querySelector('[data-share]').addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      notify('Book link copied to clipboard.');
    } catch { notify('Could not copy the link. You can copy it from the address bar.'); }
  });
  detail.querySelector('[data-delete]').addEventListener('click', async () => {
    if (!window.confirm(`Remove “${book.title}” from your shelf?`)) return;
    try {
      await request(`/api/books/${encodeURIComponent(book.id)}`, { method: 'DELETE' });
      window.location.assign('/');
    } catch (error) { notify(error.message); }
  });
}

async function loadDetail() {
  const id = location.pathname.split('/')[2];
  if (!id) return notFound();
  try { renderDetail(await request(`/api/books/${encodeURIComponent(decodeURIComponent(id))}`)); }
  catch (error) { if (error.message === 'Book not found.') notFound(); else { notFound(); notify(error.message); } }
}

document.addEventListener('click', (event) => {
  if (event.target.closest('[data-open-form]')) {
    form.reset();
    document.querySelector('#form-error').hidden = true;
    dialog.showModal();
    form.elements.title.focus();
  }
  if (event.target.closest('[data-close-form]')) dialog.close();
  if (event.target.closest('[data-retry]')) loadShelf();
});

dialog.addEventListener('click', (event) => { if (event.target === dialog) dialog.close(); });
form.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (!form.reportValidity()) return;
  const submit = form.querySelector('[type="submit"]');
  submit.disabled = true;
  const errorText = document.querySelector('#form-error');
  errorText.hidden = true;
  try {
    const book = await request('/api/books', {
      method: 'POST',
      body: JSON.stringify({ title: form.elements.title.value, author: form.elements.author.value, notes: form.elements.notes.value, status: form.elements.status.value })
    });
    window.location.assign(`/books/${encodeURIComponent(book.id)}`);
  } catch (error) {
    errorText.textContent = error.message;
    errorText.hidden = false;
    submit.disabled = false;
  }
});

dashboard.addEventListener('click', async (event) => {
  const button = event.target.closest('[data-book-id]');
  if (!button) return;
  button.disabled = true;
  try {
    await request(`/api/books/${encodeURIComponent(button.dataset.bookId)}`, { method: 'PATCH', body: JSON.stringify({ status: button.dataset.status }) });
    await loadShelf();
    notify(button.dataset.status === 'finished' ? 'Moved to finished books.' : 'Moved back to currently reading.');
  } catch (error) { button.disabled = false; notify(error.message); }
});

if (/^\/books\//.test(location.pathname)) {
  dashboard.hidden = true;
  detail.hidden = false;
  loadDetail();
} else {
  loadShelf();
}
"}

