import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { createApp } from '../server.js';

async function start(dataFile) {
  const server = createApp({ dataFile });
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  return { server, url: `http://127.0.0.1:${server.address().port}` };
}

async function call(url, path, method = 'GET', value) {
  const response = await fetch(`${url}${path}`, {
    method,
    headers: value === undefined ? {} : { 'Content-Type': 'application/json' },
    body: value === undefined ? undefined : JSON.stringify(value)
  });
  return { status: response.status, body: await response.json() };
}

test('books can be added, opened by direct link, edited, finished and retained after restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'between-pages-'));
  const dataFile = join(directory, 'books.json');
  let app;
  try {
    app = await start(dataFile);
    assert.deepEqual((await call(app.url, '/api/books')).body, []);
    const created = await call(app.url, '/api/books', 'POST', {
      title: '  The Hobbit  ', author: ' J. R. R. Tolkien ', notes: 'A beginning.', status: 'reading'
    });
    assert.equal(created.status, 201);
    assert.equal(created.body.title, 'The Hobbit');
    assert.equal(created.body.author, 'J. R. R. Tolkien');
    const id = created.body.id;
    const updated = await call(app.url, `/api/books/${id}`, 'PATCH', { notes: 'There and back again.', status: 'finished' });
    assert.equal(updated.status, 200);
    assert.equal(updated.body.notes, 'There and back again.');
    assert.ok(updated.body.finishedAt);
    assert.equal((await call(app.url, '/api/books')).body[0].status, 'finished');
    const page = await fetch(`${app.url}/books/${id}`);
    assert.equal(page.status, 200);
    assert.match(await page.text(), /Between Pages — Your reading shelf/);
    const disk = JSON.parse(await readFile(dataFile, 'utf8'));
    assert.equal(disk[0].notes, 'There and back again.');

    await new Promise((resolve) => app.server.close(resolve));
    app = await start(dataFile);
    assert.equal((await call(app.url, `/api/books/${id}`)).body.status, 'finished');
    const readingAgain = await call(app.url, `/api/books/${id}`, 'PATCH', { status: 'reading' });
    assert.equal(readingAgain.body.finishedAt, null);
    assert.equal((await call(app.url, `/api/books/${id}`, 'DELETE')).status, 200);
    assert.equal((await call(app.url, `/api/books/${id}`)).status, 404);
  } finally {
    if (app) await new Promise((resolve) => app.server.close(resolve));
    await rm(directory, { recursive: true, force: true });
  }
});

test('invalid input is rejected and concurrent additions are not lost', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'between-pages-'));
  const app = await start(join(directory, 'books.json'));
  try {
    const invalid = await call(app.url, '/api/books', 'POST', { title: '', author: 'Someone' });
    assert.equal(invalid.status, 400);
    assert.match(invalid.body.error, /Title/);
    assert.equal((await call(app.url, '/api/books', 'POST', { title: 'Book', author: 'Writer', status: 'other' })).status, 400);
    const results = await Promise.all(Array.from({ length: 12 }, (_, i) =>
      call(app.url, '/api/books', 'POST', { title: `Book ${i}`, author: 'Writer' })));
    assert.ok(results.every((result) => result.status === 201));
    assert.equal((await call(app.url, '/api/books')).body.length, 12);
    assert.equal((await call(app.url, `/api/books/${results[0].body.id}`, 'PATCH', { title: 'Changed' })).status, 400);
  } finally {
    await new Promise((resolve) => app.server.close(resolve));
    await rm(directory, { recursive: true, force: true });
  }
});
